def touch_noise(a,sqset,noise):
    H,W=a.shape
    nb=[]
    for y in range(H):
        for x in range(W):
            if a[y,x]==noise:
                nbs=[(y+dy,x+dx) for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0)]
                if any(0<=yy<H and 0<=xx<W and a[yy,xx] in sqset for yy,xx in nbs):
                    nb.append((y,x))
    return nb
