def test(n):
    a=np.array(G[f'Demo pair {n} input']); o=np.array(G[f'Demo pair {n} output'])
    cnt=Counter(a.flatten()); bg=int(cnt.most_common(1)[0][0])
    rem=sorted({c:int(c) for c in cnt if c!=bg},key=lambda c:cnt[c])
    # square color = most common non-bg; noise = other
    sq=rem[0]; noise=rem[1] if len(rem)>1 else None
    H,W=o.shape; ph,pw=a.shape[0]//H, a.shape[1]//W
    out=[]
    for i in range(H):
        row=[]
        for j in range(W):
            blk=a[i*ph:(i+1)*ph, j*pw:(j+1)*pw]
            nz=(blk==noise).any(); nqs=(blk==sq).any()
            if nz: row.append(noise)
            elif nqs: row.append(sq)
            else: row.append(bg)
        out.append(row)
    ok = out==o.tolist()
    print(n, (ph,pw),'match' if ok else 'NO', Counter(out+[list(o)]))
    return ok
for n in range(1,9): test(n)

